/* Auto-generated from uploaded graphics.py using original PIL ImageDraw primitives.
 * Text drawing was disabled; only non-background icon pixels are exported.
 * Coordinates are normalized to each icon visible bbox. X_OFFSET/Y_OFFSET record
 * the bbox offset relative to the original Python left/top.
 * Bitmap packing: MSB first, left-to-right. 1 = draw pixel, 0 = transparent/background.
 */
#pragma once
#include <stdint.h>

typedef struct { uint8_t x; uint8_t y; } IconPoint;

typedef struct {
    const uint8_t *bitmap;
    uint8_t width;
    uint8_t height;
    uint8_t bytes_per_row;
    int8_t x_offset;
    int8_t y_offset;
} IconBitmap;

typedef void (*IconPixelFn)(int x, int y, void *user);

static inline void icon_draw_bitmap_msb(const IconBitmap *icon, int left, int top, IconPixelFn put_pixel, void *user) {
    for (uint8_t y = 0; y < icon->height; ++y) {
        const uint8_t *row = icon->bitmap + (uint16_t)y * icon->bytes_per_row;
        for (uint8_t x = 0; x < icon->width; ++x) {
            if (row[x >> 3] & (uint8_t)(0x80u >> (x & 7))) {
                put_pixel(left + icon->x_offset + x, top + icon->y_offset + y, user);
            }
        }
    }
}

